contracts/Presale.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@uniswap/v2-periphery/contracts/interfaces/IUniswapV2Router02.sol";
import "./Token.sol";
import "./Staking.sol";

contract Presale is Ownable, ReentrancyGuard {
    Token public token;
    Staking public stakingContract;
    IUniswapV2Router02 public immutable pancakeRouter;
    address public liquidityVault;
    
    uint256 public initialPrice = 41406318500000 wei; // Prezzo esatto per ottenere 24151 token per 1 BNB
    uint256 public constant PRICE_INCREASE_PERCENTAGE = 1;
    uint256 public constant PRICE_INCREASE_INTERVAL = 12 hours;
    uint256 public constant TOKENS_FOR_LIQUIDITY_PERCENTAGE = 30;
    
    uint256 public presaleStartTime;
    uint256 public totalRaised;
    uint256 public totalTokensSold;
    
    mapping(address => uint256) public contributions;
    bool public presaleFinalized;

    event TokensPurchased(address indexed buyer, uint256 ethAmount, uint256 tokenAmount);
    event PresaleFinalized(uint256 ethAmount, uint256 tokenAmount);
    event RemainingTokensStaked(uint256 amount);

    constructor(
        address _token,
        address _pancakeRouter,
        address _stakingContract,
        address _liquidityVault
    ) {
        require(_token != address(0), "Invalid token address");
        require(_pancakeRouter != address(0), "Invalid router address");
        require(_stakingContract != address(0), "Invalid staking address");
        require(_liquidityVault != address(0), "Invalid liquidity vault address");
        token = Token(_token);
        pancakeRouter = IUniswapV2Router02(_pancakeRouter);
        stakingContract = Staking(_stakingContract);
        liquidityVault = _liquidityVault;
        presaleStartTime = block.timestamp;
    }

    function getCurrentPrice() public view returns (uint256) {
        uint256 elapsedIntervals = (block.timestamp - presaleStartTime) / PRICE_INCREASE_INTERVAL;
        uint256 priceIncrease = initialPrice * elapsedIntervals * PRICE_INCREASE_PERCENTAGE / 100;
        return initialPrice + priceIncrease;
    }

    function setInitialPrice(uint256 _newPrice) external onlyOwner {
        require(_newPrice > 0, "Price must be greater than 0");
        initialPrice = _newPrice;
    }

    function participate() external payable nonReentrant {
        require(!presaleFinalized, "Presale finalized");
        require(address(token) != address(0), "Token not set");

        uint256 currentPrice = getCurrentPrice();
        uint256 tokenAmount = (msg.value * 1 ether) / currentPrice;

        contributions[msg.sender] += msg.value;
        totalRaised += msg.value;
        totalTokensSold += tokenAmount;

        require(token.transfer(msg.sender, tokenAmount), "Token transfer failed");

        emit TokensPurchased(msg.sender, msg.value, tokenAmount);
    }

    function finalize() external onlyOwner {
        require(!presaleFinalized, "Already finalized");
        require(address(token) != address(0), "Token not set");
        
        presaleFinalized = true;

        // Usa tutti i token dal LiquidityVault per la liquidità
        uint256 tokensForLiquidity = token.balanceOf(liquidityVault);
        
        // Trasferisci i token dal LiquidityVault al contratto
        require(token.transferFrom(liquidityVault, address(this), tokensForLiquidity), "Transfer from liquidity vault failed");
        
        // Approva il router PancakeSwap
        token.approve(address(pancakeRouter), tokensForLiquidity);
        
        // Aggiungi liquidità a PancakeSwap con i BNB raccolti
        pancakeRouter.addLiquidityETH{value: totalRaised}(
            address(token),
            tokensForLiquidity,
            0, // slippage configurato a 100% per semplicità
            0, // slippage configurato a 100% per semplicità
            owner(),
            block.timestamp + 300
        );

        // Metti in staking i token rimanenti del presale
        uint256 remainingPresaleTokens = token.balanceOf(address(this));
        if (remainingPresaleTokens > 0) {
            // Approva lo staking contract
            token.approve(address(stakingContract), remainingPresaleTokens);
            
            // Stake dei token rimanenti
            stakingContract.stake(remainingPresaleTokens);
            
            emit RemainingTokensStaked(remainingPresaleTokens);
        }

        emit PresaleFinalized(totalRaised, tokensForLiquidity);
    }

    // View function per il frontend
    function getTokensForBNB(uint256 bnbAmount) public view returns (uint256) {
        uint256 currentPrice = getCurrentPrice();
        return (bnbAmount * 1 ether) / currentPrice;
    }

    receive() external payable {}
}

contracts/Staking.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract Staking is ReentrancyGuard, Ownable {
    IERC20 public stakingToken;
    
    // APR settings
    uint256 public constant APR_MAX = 150; // 150% maximum APR
    uint256 public constant APR_MIN = 3;   // 3% minimum APR
    uint256 public constant MIN_LIQUIDITY_THRESHOLD = 5; // 5% minimum liquidity threshold
    uint256 public constant MAX_APR_THRESHOLD = 200_000_000 * 1e18; // 200M tokens threshold for max APR
    
    // Staking settings
    uint256 public minimumStakingPeriod; // Minimum time tokens must be staked
    uint256 public totalStaked;

    struct StakeInfo {
        uint256 amount;
        uint256 startTime;
        uint256 lastClaimTime;
        uint256 unclaimableRewards;
    }

    mapping(address => StakeInfo) public stakes;
    address[] private stakersArray;

    event Staked(address indexed user, uint256 amount);
    event Withdrawn(address indexed user, uint256 amount);
    event RewardsClaimed(address indexed user, uint256 reward);

    constructor(
        address _stakingToken,
        uint256 _minimumStakingPeriod
    ) {
        require(_stakingToken != address(0), "Invalid token address");
        stakingToken = IERC20(_stakingToken);
        minimumStakingPeriod = _minimumStakingPeriod;
    }

    function getCurrentAPR() public view returns (uint256) {
        uint256 contractBalance = stakingToken.balanceOf(address(this));
        
        // Se il bilancio è maggiore o uguale a 200M tokens, ritorna APR massimo
        if (contractBalance >= MAX_APR_THRESHOLD) {
            return APR_MAX;
        }
        
        // Calculate liquidity percentage (0-100)
        uint256 liquidityPercentage = (contractBalance * 100) / MAX_APR_THRESHOLD;
        
        // If liquidity is at or below minimum threshold, return minimum APR
        if (liquidityPercentage <= MIN_LIQUIDITY_THRESHOLD) {
            return APR_MIN;
        }
        
        // Calculate dynamic APR using the formula:
        // APR = APR_max - (APR_max - APR_min) × (1 - liquidityPercentage/100)
        uint256 aprRange = APR_MAX - APR_MIN;
        uint256 liquidityFactor = (liquidityPercentage * 1e18) / 100; // Use 1e18 for precision
        
        uint256 aprReduction = (aprRange * (1e18 - liquidityFactor)) / 1e18;
        return APR_MAX - aprReduction;
    }

    function calculateRewards(address _staker) public view returns (uint256) {
        if (stakes[_staker].amount == 0) {
            return 0;
        }

        uint256 timeElapsed = block.timestamp - stakes[_staker].lastClaimTime;
        
        // Calculate reward rate based on current APR
        uint256 currentAPR = getCurrentAPR();
        uint256 annualReward = (stakes[_staker].amount * currentAPR) / 100;
        uint256 rewardPerSecond = annualReward / 365 days;
        uint256 pendingReward = rewardPerSecond * timeElapsed;
        
        // Verifica che ci siano abbastanza token nel contratto per pagare le ricompense
        uint256 contractBalance = stakingToken.balanceOf(address(this));
        if (pendingReward > contractBalance) {
            pendingReward = contractBalance;
        }
        
        return pendingReward;
    }

    function stake(uint256 _amount) external nonReentrant {
        require(_amount > 0, "Cannot stake 0");
        
        // Update rewards before modifying stake
        uint256 pendingReward = calculateRewards(msg.sender);
        stakes[msg.sender].unclaimableRewards += pendingReward;
        
        // Transfer tokens to contract
        require(stakingToken.transferFrom(msg.sender, address(this), _amount), "Transfer failed");
        
        // Update stake info
        if (stakes[msg.sender].amount == 0) {
            stakes[msg.sender].startTime = block.timestamp;
            stakes[msg.sender].lastClaimTime = block.timestamp;
            stakersArray.push(msg.sender);
        }
        
        stakes[msg.sender].amount += _amount;
        totalStaked += _amount;
        
        emit Staked(msg.sender, _amount);
    }

    function withdraw(uint256 _amount) external nonReentrant {
        require(_amount > 0 && _amount <= stakes[msg.sender].amount, "Invalid amount");
        require(
            block.timestamp >= stakes[msg.sender].startTime + minimumStakingPeriod,
            "Minimum staking period not met"
        );
        
        // Update rewards before modifying stake
        uint256 pendingReward = calculateRewards(msg.sender);
        stakes[msg.sender].unclaimableRewards += pendingReward;
        
        // Update stake info
        stakes[msg.sender].amount -= _amount;
        totalStaked -= _amount;
        
        // Transfer tokens back to user
        require(stakingToken.transfer(msg.sender, _amount), "Transfer failed");
        
        emit Withdrawn(msg.sender, _amount);
    }

    function claimRewards() external nonReentrant {
        uint256 rewards = calculateRewards(msg.sender) + stakes[msg.sender].unclaimableRewards;
        require(rewards > 0, "No rewards to claim");
        
        stakes[msg.sender].lastClaimTime = block.timestamp;
        stakes[msg.sender].unclaimableRewards = 0;
        
        require(stakingToken.transfer(msg.sender, rewards), "Reward transfer failed");
        
        emit RewardsClaimed(msg.sender, rewards);
    }

    // Admin functions
    function updateMinimumStakingPeriod(uint256 _newPeriod) external onlyOwner {
        minimumStakingPeriod = _newPeriod;
    }

    // View functions
    function getStakeInfo(address _staker) external view returns (
        uint256 amount,
        uint256 startTime,
        uint256 pendingRewards
    ) {
        StakeInfo memory stake = stakes[_staker];
        return (
            stake.amount,
            stake.startTime,
            calculateRewards(_staker) + stake.unclaimableRewards
        );
    }

    // Burn function
    function burn(uint256 amount) external onlyOwner {
        uint256 contractBalance = stakingToken.balanceOf(address(this));
        uint256 totalPendingRewards = 0;
        
        // Calcola il totale delle ricompense in sospeso per tutti gli staker
        for(uint i = 0; i < stakersArray.length; i++) {
            if(stakes[stakersArray[i]].amount > 0) {
                totalPendingRewards += calculateRewards(stakersArray[i]) + 
                                     stakes[stakersArray[i]].unclaimableRewards;
            }
        }
        
        // Assicurati che ci siano abbastanza token per le ricompense dopo il burn
        require(contractBalance >= amount + totalPendingRewards, "Insufficient balance to burn");
        require(stakingToken.transfer(address(0xdead), amount), "Burn transfer failed");
    }
}

contracts/Swap.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

contract Swap is Ownable, ReentrancyGuard {
    IERC20 public sopToken;
    uint256 public ethToSopRate = 1000; // 1 ETH = 1000 SOP (esempio)
    uint256 public sopToEthRate = 1000; // 1000 SOP = 1 ETH

    event TokensPurchased(address indexed buyer, uint256 ethAmount, uint256 tokenAmount);
    event TokensSold(address indexed seller, uint256 tokenAmount, uint256 ethAmount);
    event RatesUpdated(uint256 newEthToSopRate, uint256 newSopToEthRate);

    constructor(address _sopToken) {
        sopToken = IERC20(_sopToken);
    }

    // Funzione per comprare token SOP con ETH
    function buyTokens() external payable nonReentrant {
        require(msg.value > 0, "Must send ETH");
        
        uint256 tokenAmount = (msg.value * ethToSopRate) / 1 ether;
        require(sopToken.balanceOf(address(this)) >= tokenAmount, "Insufficient token balance in contract");

        bool success = sopToken.transfer(msg.sender, tokenAmount);
        require(success, "Token transfer failed");

        emit TokensPurchased(msg.sender, msg.value, tokenAmount);
    }

    // Funzione per vendere token SOP per ETH
    function sellTokens(uint256 tokenAmount) external nonReentrant {
        require(tokenAmount > 0, "Must sell some tokens");
        require(sopToken.balanceOf(msg.sender) >= tokenAmount, "Insufficient token balance");

        uint256 ethAmount = (tokenAmount * 1 ether) / sopToEthRate;
        require(address(this).balance >= ethAmount, "Insufficient ETH balance in contract");

        bool success = sopToken.transferFrom(msg.sender, address(this), tokenAmount);
        require(success, "Token transfer failed");

        (bool sent, ) = msg.sender.call{value: ethAmount}("");
        require(sent, "ETH transfer failed");

        emit TokensSold(msg.sender, tokenAmount, ethAmount);
    }

    // Funzione per aggiornare i tassi di cambio (solo owner)
    function updateRates(uint256 newEthToSopRate, uint256 newSopToEthRate) external onlyOwner {
        require(newEthToSopRate > 0 && newSopToEthRate > 0, "Invalid rates");
        ethToSopRate = newEthToSopRate;
        sopToEthRate = newSopToEthRate;
        emit RatesUpdated(newEthToSopRate, newSopToEthRate);
    }

    // Funzione per ritirare ETH (solo owner)
    function withdrawETH() external onlyOwner {
        uint256 balance = address(this).balance;
        require(balance > 0, "No ETH to withdraw");
        
        (bool sent, ) = msg.sender.call{value: balance}("");
        require(sent, "ETH transfer failed");
    }

    // Funzione per ritirare token (solo owner)
    function withdrawTokens(uint256 amount) external onlyOwner {
        require(amount > 0, "Amount must be greater than 0");
        require(sopToken.balanceOf(address(this)) >= amount, "Insufficient token balance");
        
        bool success = sopToken.transfer(msg.sender, amount);
        require(success, "Token transfer failed");
    }

    // Funzione per ottenere la stima dei token in output
    function getEstimatedTokens(uint256 ethAmount) external view returns (uint256) {
        return (ethAmount * ethToSopRate) / 1 ether;
    }

    // Funzione per ottenere la stima di ETH in output
    function getEstimatedEth(uint256 tokenAmount) external view returns (uint256) {
        return (tokenAmount * 1 ether) / sopToEthRate;
    }

    // Funzione per ricevere ETH
    receive() external payable {}
}

contracts/Token.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract Token is ERC20, Ownable {
    address public presaleContract;
    address public stakingContract;
    address public airdropContract;
    address public liquidityVaultContract;
    struct LockInfo {
        uint256 amount;
        uint256 lockEndTime;
        uint256 partialUnlockTime;
    }
    
    mapping(address => LockInfo[]) public userLocks;
    uint256 public defaultPartialUnlockTime;
    uint256 public defaultFullUnlockTime;
    
    uint256 public STAKING_TAX = 2; // 2% tax for staking
    uint256 public AIRDROP_TAX = 2; // 2% tax for airdrop
    uint256 public constant INITIAL_SUPPLY = 1_000_000_000; // 1 billion tokens
    uint256 public maxWalletPercentage = 100; // 100% initially, can be changed through admin page
    bool public mintingEnabled = true;

    constructor() ERC20("SOP", "SOP") {
        if(mintingEnabled) {
            _mint(msg.sender, INITIAL_SUPPLY * 10 ** decimals());
        }
    }

    function setMaxWalletPercentage(uint256 _percentage) external onlyOwner {
        require(_percentage > 0 && _percentage <= 100, "Invalid percentage");
        maxWalletPercentage = _percentage;
    }

    function toggleMinting() external onlyOwner {
        mintingEnabled = !mintingEnabled;
    }

    function setStakingTax(uint256 _newTax) external onlyOwner {
        require(_newTax <= 10, "Tax cannot exceed 10%");
        STAKING_TAX = _newTax;
    }

    function setAirdropTax(uint256 _newTax) external onlyOwner {
        require(_newTax <= 10, "Tax cannot exceed 10%");
        AIRDROP_TAX = _newTax;
    }

    function setDefaultUnlockTimes(uint256 _partialUnlockTime, uint256 _fullUnlockTime) external onlyOwner {
        require(_partialUnlockTime < _fullUnlockTime, "Invalid unlock times");
        defaultPartialUnlockTime = _partialUnlockTime;
        defaultFullUnlockTime = _fullUnlockTime;
    }

    function setPresaleContract(address _presale) external onlyOwner {
        presaleContract = _presale;
    }

    function setStakingContract(address _staking) external onlyOwner {
        stakingContract = _staking;
    }

    function setAirdropContract(address _airdrop) external onlyOwner {
        airdropContract = _airdrop;
    }

    function setLiquidityVaultContract(address _liquidityVault) external onlyOwner {
        liquidityVaultContract = _liquidityVault;
    }

    function lockTokens(address account, uint256 amount, uint256 fullUnlockTime, uint256 _partialUnlockTime) external {
        require(msg.sender == presaleContract, "Only presale can lock");
        userLocks[account].push(LockInfo({
            amount: amount,
            lockEndTime: fullUnlockTime > 0 ? fullUnlockTime : defaultFullUnlockTime,
            partialUnlockTime: _partialUnlockTime > 0 ? _partialUnlockTime : defaultPartialUnlockTime
        }));
    }

    function _transfer(
        address sender,
        address recipient,
        uint256 amount
    ) internal virtual override {
        require(sender != address(0), "Transfer from zero address");
        require(recipient != address(0), "Transfer to zero address");

        // Check max wallet percentage
        if (recipient != presaleContract && 
            recipient != stakingContract && 
            recipient != airdropContract && 
            recipient != liquidityVaultContract &&
            recipient != owner()) {
            uint256 maxWalletAmount = (INITIAL_SUPPLY * maxWalletPercentage) / 100;
            require(
                balanceOf(recipient) + amount <= maxWalletAmount * 10 ** decimals(),
                "Exceeds max wallet amount"
            );
        }

        // Skip tax for special addresses
        bool skipTax = sender == presaleContract || 
                      recipient == presaleContract ||
                      sender == stakingContract || 
                      recipient == stakingContract ||
                      sender == airdropContract ||
                      recipient == airdropContract ||
                      sender == liquidityVaultContract ||
                      recipient == liquidityVaultContract ||
                      sender == owner() ||
                      recipient == owner();

        uint256 stakingTaxAmount = 0;
        uint256 airdropTaxAmount = 0;
        if (!skipTax) {
            stakingTaxAmount = (amount * STAKING_TAX) / 100;
            airdropTaxAmount = (amount * AIRDROP_TAX) / 100;
        }

        // Se il destinatario è il contratto di staking o airdrop, permetti sempre il trasferimento
        if (recipient == stakingContract || recipient == airdropContract) {
            super._transfer(sender, recipient, amount);
            return;
        }

        // Gestione dei token bloccati
        uint256 totalLocked = 0;
        for (uint i = 0; i < userLocks[sender].length; i++) {
            LockInfo storage lock = userLocks[sender][i];
            if (lock.amount > 0) {
                if (block.timestamp >= lock.lockEndTime) {
                    // Periodo di lock completamente terminato
                    lock.amount = 0;
                } else if (block.timestamp >= lock.partialUnlockTime) {
                    // Periodo di lock parziale terminato (30% sbloccato)
                    uint256 stillLocked = (lock.amount * 70) / 100;
                    totalLocked += stillLocked;
                } else {
                    totalLocked += lock.amount;
                }
            }
        }

        if (totalLocked > 0) {
            uint256 availableTokens = balanceOf(sender) - totalLocked;
            require(amount <= availableTokens, "Transfer amount exceeds unlocked balance");
        }

        uint256 totalTax = stakingTaxAmount + airdropTaxAmount;
        if (totalTax > 0) {
            if (stakingTaxAmount > 0 && stakingContract != address(0)) {
                super._transfer(sender, stakingContract, stakingTaxAmount);
            }
            if (airdropTaxAmount > 0 && airdropContract != address(0)) {
                super._transfer(sender, airdropContract, airdropTaxAmount);
            }
            super._transfer(sender, recipient, amount - totalTax);
        } else {
            super._transfer(sender, recipient, amount);
        }
    }

    function burn(uint256 amount) public {
        _burn(msg.sender, amount);
    }

    // View functions per il frontend
    function getLockedTokens(address account) public view returns (uint256) {
        uint256 totalLocked = 0;
        for (uint i = 0; i < userLocks[account].length; i++) {
            LockInfo memory lock = userLocks[account][i];
            if (lock.amount > 0) {
                if (block.timestamp >= lock.lockEndTime) {
                    continue;
                } else if (block.timestamp >= lock.partialUnlockTime) {
                    totalLocked += (lock.amount * 70) / 100;
                } else {
                    totalLocked += lock.amount;
                }
            }
        }
        return totalLocked;
    }

    function getUserLockInfo(address account, uint256 index) public view returns (uint256, uint256, uint256) {
        require(index < userLocks[account].length, "Invalid lock index");
        LockInfo memory lock = userLocks[account][index];
        return (lock.amount, lock.partialUnlockTime, lock.lockEndTime);
    }

    function getUserLocksCount(address account) public view returns (uint256) {
        return userLocks[account].length;
    }


}

